    /** Original grouped menu. New workflows require separately verified activation. */
    public static function navigation(string $lang,string $view,bool $manage=true,string $office='',bool $workspace=false): string
    {
        $ar=$lang==='ar';$q='?lang='.$lang.($office!==''?'&office='.rawurlencode($office):'');
        $groups=[
          [$ar?'القائمة الرئيسية':'Main menu',[['overview','chart-pie','لوحة التحكم','Dashboard']]],
          [$ar?'المالية والحسابات':'Finance & accounts',[
            ['treasury','vault','الخزنة والإيداعات','Treasury & deposits'],['receipts','file-invoice-dollar','إيصالات الاستلام (سند قبض)','Cash receipt vouchers'],
            ['expenses','receipt','سجل المصروفات','Expense register'],['advances','hand-holding-dollar','العهد والمرتجعات','Advances & returns'],
            ['categories','tags','بنود المصروفات','Expense categories'],['reports','chart-line','التقارير المالية','Financial reports']]],
          [$ar?'الموارد البشرية والرواتب':'Human resources & payroll',[
            ['employees','users','دليل الموظفين','Employee directory'],['payroll','money-check-dollar','مسيرات الرواتب','Payroll']]],
          [$ar?'إدارة الشركة':'Company management',[
            ['settings','building-gear','إعدادات الشركة والمقر','Company & office settings'],['users','user-shield','مستخدمي الشركة','Company users']]],
        ];
        $e=fn($v)=>htmlspecialchars($v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$html='';
        foreach($groups as[$heading,$items]){
            $html.='<p class="nav-label">'.$e($heading).'</p>';
            foreach($items as[$key,$icon,$arabic,$english]){
                if($key==='users'&&!$manage)continue;
                $label=$ar?$arabic:$english;$enabled=$workspace||in_array($key,['overview','expenses','advances','users'],true);
                $content='<i class="fa-solid fa-'.$icon.'" aria-hidden="true"></i><span>'.$e($label).'</span>';
                if($enabled){$href=$key==='users'?'users.php'.$q:($workspace&&$key!=='overview'?'workspace.php'.$q.'&view='.$key:'index.php'.$q.'&view='.$key);
                    $html.='<a class="nav-link'.($view===$key?' active':'').'" href="'.$e($href).'"'.($view===$key?' aria-current="page"':'').'>'.$content.'</a>';
                }else{$html.='<span class="nav-link nav-unavailable" aria-disabled="true">'.$content.'<small>'.($ar?'قريبًا':'Pending').'</small></span>';}
            }
        }
        return $html;
    }

