        ['title'=>'Company users','intro'=>'Assign existing Dolibarr staff to branches with separate permissions.','branch'=>'Branch','egypt'=>'Egypt','china'=>'China','staff'=>'Dolibarr staff','select'=>'Select staff','open'=>'View permissions','name'=>'Name / login','permissions'=>'Permissions','status'=>'Status','active'=>'Active','revoked'=>'Access revoked','edit'=>'Edit','revoke'=>'Remove from branch','save'=>'Save assignment','expenses'=>'Expenses','advances'=>'Advances & returns','none'=>'No access','read'=>'Read only','create'=>'Read and create drafts','scope'=>'Record visibility','own'=>'Staff member’s own records','all'=>'Branch records','back'=>'Office expenses','note'=>'Removing membership preserves the Dolibarr account and history. Financial edits and cancellations are unavailable at this stage.','empty'=>'No assignments for this branch.','error'=>'The request could not be completed. Check access and refresh the page before retrying.','supported'=>'Draft creation and viewing are available. Record editing, deletion and other sections are not enabled yet.','revision'=>'Revision','cancel'=>'Cancel','confirm'=>'Confirm removing this staff member’s access to this branch','account'=>'Manage accounts, passwords and native module capabilities in Dolibarr. Branch grants operate within those capabilities.'];
        $selected=$state['selected'];$membership=null;foreach($state['members']as$row)if($selected&&$row['user_id']===$selected['id'])$membership=$row;
        $url=fn($office,$id=null)=>'users.php?lang='.$lang.'&office='.$office.($id!==null?'&staff_id='.$id:'');
