    private function permissionRow(string $section,string $label,?array $membership,bool $expanded,bool $ar,array $t): string
    {
        $e=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
        $grants=($membership['active']??false)?($membership['grants'][$section]??[]):[];
        $h='<tr><th scope="row">'.$e($label).'</th><td>';
        if($expanded){foreach(['read','create']as$action){if(!in_array($action,OfficeExpenseStaffAccess::ACTIONS[$section],true))continue;$id='grant-'.$section.'-'.$action;$h.='<label class="staff-action-check" for="'.$id.'"><input type="checkbox" id="'.$id.'" name="permissions['.$section.'][]" value="'.$action.'"'.(in_array($action,$grants,true)?' checked':'').'> '.$e($action==='read'?($ar?'عرض':'Read'):($ar?'إنشاء':'Create')).'</label>';}}
        elseif(in_array($section,['expenses','advances'],true)){$current=in_array('create',$grants,true)?'create':(in_array('read',$grants,true)?'read':'none');$h.='<label class="sr-only" for="grant-'.$section.'">'.$e($label).'</label><select id="grant-'.$section.'" name="permissions['.$section.']">';foreach(['none','read','create']as$level)$h.='<option value="'.$level.'"'.($current===$level?' selected':'').'>'.$e($t[$level]).'</option>';$h.='</select>';}
        else $h.='<span class="permission-unavailable">'.($ar?'غير مفعّل':'Unavailable').'</span>';
        $h.='</td>';foreach(['update','delete']as$action){$h.='<td>';if($expanded&&in_array($action,OfficeExpenseStaffAccess::ACTIONS[$section],true)){$id='grant-'.$section.'-'.$action;$h.='<label class="staff-action-check" for="'.$id.'"><input type="checkbox" id="'.$id.'" name="permissions['.$section.'][]" value="'.$action.'"'.(in_array($action,$grants,true)?' checked':'').'> '.$e($action==='update'?($ar?'تعديل':'Edit'):($ar?'أرشفة واسترجاع':'Archive / restore')).'</label>';}else $h.='<span class="permission-unavailable">'.($expanded?'—':($ar?'غير مفعّل':'Unavailable')).'</span>';$h.='</td>';}
        return $h.'</tr>';
    }

